#!/usr/bin/env python3
"""Generate a simple LaTeX redline from *_original.tex and edited *.tex files.

This is intentionally dependency-light. It compares TeX line-by-line, which works
well for Pandoc-converted manuscripts where each paragraph is usually one line.
Deleted lines are shown in red strikethrough; added lines are shown in blue.
"""

from __future__ import annotations

import argparse
import difflib
import subprocess
from pathlib import Path

REDLINE_MACROS = r"""
% Redline macros generated by make_redline.py.
% Deleted text is red struck-through; added text is blue.
\providecommand{\DIFadd}[1]{{\begingroup\color{blue}#1\endgroup}}
\providecommand{\DIFdel}[1]{{\begingroup\color{red}\sout{#1}\endgroup}}
""".strip()

DEFAULT_PAIRS = [
    ("main_original.tex", "main.tex", "main_redline.tex"),
    ("sm_original.tex", "sm.tex", "sm_redline.tex"),
]


def inject_macros(text: str) -> str:
    if "\\providecommand{\\DIFadd}" in text and "\\providecommand{\\DIFdel}" in text:
        return text
    marker = "\\begin{document}"
    if marker not in text:
        raise ValueError("Cannot find \\begin{document}; refusing to create redline.")
    return text.replace(marker, REDLINE_MACROS + "\n\n" + marker, 1)


def wrap_added(line: str) -> str:
    if not line.strip():
        return line
    return f"\\DIFadd{{{line.rstrip(chr(10))}}}\n"


def wrap_deleted(line: str) -> str:
    if not line.strip():
        return line
    return f"\\DIFdel{{{line.rstrip(chr(10))}}}\n"


def make_redline(old_path: Path, new_path: Path, out_path: Path) -> None:
    old_lines = old_path.read_text(encoding="utf-8").splitlines(keepends=True)
    new_lines = new_path.read_text(encoding="utf-8").splitlines(keepends=True)
    matcher = difflib.SequenceMatcher(a=old_lines, b=new_lines, autojunk=False)

    output: list[str] = []
    for tag, i1, i2, j1, j2 in matcher.get_opcodes():
        if tag == "equal":
            output.extend(new_lines[j1:j2])
        elif tag == "delete":
            output.extend(wrap_deleted(line) for line in old_lines[i1:i2])
        elif tag == "insert":
            output.extend(wrap_added(line) for line in new_lines[j1:j2])
        elif tag == "replace":
            output.extend(wrap_deleted(line) for line in old_lines[i1:i2])
            output.extend(wrap_added(line) for line in new_lines[j1:j2])
        else:
            raise RuntimeError(f"Unexpected diff tag: {tag}")

    out_path.write_text(inject_macros("".join(output)), encoding="utf-8")


def compile_tex(tex_path: Path) -> None:
    for _ in range(2):
        subprocess.run(
            ["xelatex", "-interaction=nonstopmode", "-halt-on-error", tex_path.name],
            cwd=tex_path.parent,
            check=True,
        )


def clean_aux(tex_path: Path) -> None:
    stem = tex_path.with_suffix("")
    for suffix in [".aux", ".log", ".out", ".toc", ".lof", ".lot", ".fls", ".fdb_latexmk", ".synctex.gz"]:
        path = stem.with_suffix(suffix)
        if path.exists():
            path.unlink()


def main() -> int:
    parser = argparse.ArgumentParser(description="Generate redline TeX/PDF files from original and edited TeX.")
    parser.add_argument("old", nargs="?", help="Original TeX file. Defaults to main/sm originals in this folder.")
    parser.add_argument("new", nargs="?", help="Edited TeX file.")
    parser.add_argument("out", nargs="?", help="Output redline TeX file.")
    parser.add_argument("--no-compile", action="store_true", help="Only write redline TeX; do not run xelatex.")
    parser.add_argument("--keep-logs", action="store_true", help="Keep LaTeX aux/log files after compilation.")
    args = parser.parse_args()

    root = Path(__file__).resolve().parent
    if args.old or args.new or args.out:
        if not (args.old and args.new and args.out):
            parser.error("Provide old, new, and out together, or provide no positional args for defaults.")
        pairs = [(args.old, args.new, args.out)]
    else:
        pairs = DEFAULT_PAIRS

    for old_name, new_name, out_name in pairs:
        old_path = (root / old_name).resolve()
        new_path = (root / new_name).resolve()
        out_path = (root / out_name).resolve()
        make_redline(old_path, new_path, out_path)
        print(f"wrote {out_path.relative_to(root)}")
        if not args.no_compile:
            compile_tex(out_path)
            if not args.keep_logs:
                clean_aux(out_path)
            print(f"wrote {out_path.with_suffix('.pdf').relative_to(root)}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
